export type ContextSnapshot = { 
/**
 * The agent's own word for whether this is the running session or its last
 * completed run.
 */
live: boolean, 
/**
 * The model the snapshot was taken on, as the agent spells it.
 */
model: string, 
/**
 * What the runtime counts in the window, and how large the window is.
 * `None` on a line that did not parse, which is the only pair that can be
 * missing without the block being unusable.
 */
used: number | null, max: number | null, 
/**
 * When compaction last ran, in the agent's words.
 */
compaction: string | null, 
/**
 * The breakdown, in the order the agent wrote it.
 */
components: Array<ContextComponent>, };

export type ContextWindow = { usedTokens: number, maxTokens: number, };

/**
 * One child the agent delegated to.
 *
 * Every field but the status is optional, because the agent fills what it knows
 * and a row this build cannot name is still a row the reader is owed: an
 * unnamed child that is *running* is worth more on screen than nothing.
 */
export type DelegatedMember = { 
/**
 * The child Session's own id — mcode's, never this app's. It is what the
 * roster is keyed by and what correlates nothing in the transcript.
 */
sessionId: string, parentSessionId: string, 
/**
 * The agent it runs as — `explore`, `worker`, `verifier` or a custom name.
 */
agentName: string | null, 
/**
 * The short title the spawning call gave it, where it named one.
 */
task: string | null, 
/**
 * `queued`, `running`, `completed`, `failed`, `stopped` or `unknown` — the
 * agent's own vocabulary, carried verbatim so a word added later draws as
 * itself rather than as nothing.
 */
status: string, 
/**
 * The background task this child belongs to, where it is a background one.
 * The only handle that ever correlates a roster row to a tool call.
 */
backgroundTaskId: string | null, errorMessage: string | null, };

/**
 * The roster, shaped for the webview.
 *
 * Carries *this* app's session id rather than the wire's, so the frontend
 * routes it into the session it already holds — mcode's own id lives on the
 * index entry and nowhere the listener reads.
 */
export type DelegationEvent = { sessionId: string, members: Array<DelegatedMember>, };

/**
 * What a stop did, counted.
 *
 * Three numbers rather than the agent's four id lists: the reader's question is
 * whether the work stopped, and a list of child session ids is a fact nothing
 * on screen can draw.
 */
export type DelegationStop = { stopped: number, active: number, failed: number, };

/**
 * Incremental content for a block.
 *
 * **Deltas are a preview, never the source of truth**: the committed event for
 * the same [`BlockRef`] supersedes whatever they accumulated. Absent deltas are
 * the common case — Codex emits none, Claude Code none for subagent output — so
 * consumers must render correctly without them.
 * Tagged on `delta`, not `type`: [`AgentEventPayload::Delta`] is a newtype
 * variant, so these fields flatten into the payload object alongside its own
 * `type` tag. Two tags of the same name serialize but never deserialize.
 */
export type DeltaEvent = { "delta": "block_start", block: BlockRef, blockType: BlockType, } | { "delta": "text_delta", block: BlockRef, text: string, } | { "delta": "input_delta", block: BlockRef, partialJson: string, } | { "delta": "block_stop", block: BlockRef, };

/**
 * One row in the Files view's tree.
 */
export type DirEntry = { name: string, 
/**
 * Relative to the session's directory, `/`-joined. The key the tree caches
 * its listings under and the one it expands on, so it is the whole of what
 * a row has to carry back.
 */
path: string, isDir: boolean, 
/**
 * Dimmed rather than hidden, the way VS Code draws one.
 */
ignored: boolean, };

/**
 * Progress for the settings tab's bar.
 *
 * Emitted rather than returned because a download outlives the dialog that
 * started it — closing settings mid-download must not cancel it, and reopening
 * must find it still running.
 */
export type DownloadProgress = { modelId: string, received: number, total: number, 
/**
 * Set once, on the last event, when the model failed to land.
 */
error: string | null, 
/**
 * The reader called it off. Terminal, like `error`, and **not** derivable
 * from the counts: a cancel is over without being complete, so the closing
 * event carried `received: 0` against a non-zero total and the listener —
 * which ends an entry on `error` or `received >= total` — read it as
 * ordinary progress and put the row back at 0%, stuck offering Cancel for a
 * task that was already gone.
 */
cancelled: boolean, };

export type Effort = "low" | "medium" | "high" | "xhigh" | "max" | "ultra";

export type ErrorSource = "harness" | "parser" | "process";

/**
 * What an `active` goal is waiting on.
 *
 * **The status stays `active` while this is set**, which is the vendor's own
 * rule: a wait is an execution detail inside a running goal, not a lifecycle
 * state. The band draws the wait's phrase where the status word would go.
 */
export type ExecutionWait = { 
/**
 * The runtime's vocabulary: `questionnaire`, `permission`, `plan`,
 * `required_background`, `automation_owner_conflict`,
 * `dependency_unavailable`, `verification`, `unknown`. A `String` for the
 * reason every other reader here gives — a reason added after this build
 * must draw as itself rather than fail the line that carried it.
 */
reason: string, };

/**
 * An installed app a path can be handed to.
 */
export type ExternalApp = { 
/**
 * The bundle's absolute path, and the app's address everywhere else here.
 *
 * Deliberately not a bundle identifier. `open -b` hands the id to Launch
 * Services, which picks whichever copy it has indexed — so a second
 * install of an editor, or a stale index, silently opens the wrong one.
 * The scan found this bundle by path; the path is what it knows.
 */
path: string, name: string, kind: ExternalAppKind, 
/**
 * The app's own icon as a `data:` PNG, or `None` where none could be read.
 * Absent is ordinary — a bundle can keep its icon in an asset catalog with
 * no `.icns` beside it — so the button falls back to a glyph rather than
 * treating this as a failure.
 */
icon: string | null, };

/**
 * Which run of the menu an app belongs to. Not cosmetic: "open in Cursor" and
 * "open in Ghostty" are different asks, and a flat list of both reads as one.
 */
export type ExternalAppKind = "editor" | "terminal" | "files";

/**
 * What the viewer draws, or the sentence saying why it draws nothing.
 *
 * No `unknown` catch-all, unlike the persisted types: this never reaches disk,
 * so an older build can never be asked to read a shape it has not heard of.
 */
export type FileBody = { "kind": "text", text: string, } | { "kind": "image", 
/**
 * A `data:` URL rather than a path: the asset protocol is scoped to
 * the attachments directory and must stay scoped, so a file anywhere
 * else has no URL the webview can fetch.
 */
dataUrl: string, };

export type FileChange = "add" | "update" | "delete";

export type FileEdit = { path: string, change: FileChange, unifiedDiff: string | null, };

/**
 * One row in the picker. `path` is relative to the indexed directory, which is
 * also what gets typed into the prompt — the CLI resolves `@path` against the
 * same cwd the child was spawned in, so no rewriting is needed on either side.
 */
export type FileMatch = { path: string, 
/**
 * The last segment, split out so the row can weight the name over the
 * directory rather than making the reader find it inside the path.
 */
name: string, 
/**
 * Everything before `name`, without a trailing slash. Empty at the root.
 */
dir: string, };

/**
 * Both sides of one file's change, as the text a diff viewer compares.
 */
export type FileVersions = { 
/**
 * `None` for a file the baseline didn't have — the viewer draws an
 * addition rather than a diff against the empty string.
 */
oldText: string | null, 
/**
 * `None` for a file the turn deleted.
 */
newText: string | null, 
/**
 * Set when a side exists but is being withheld, so the panel can name the
 * reason instead of drawing an empty diff and looking broken.
 */
unreadable: Unreadable | null, };

/**
 * Who `gh` is signed in as, and what its credential may read.
 */
export type GhAccount = { 
/**
 * Where the credential came from — `keyring` for `gh auth login`, or the
 * name of the variable when a token was handed in from the environment.
 * **The distinction matters to the cure**: one is refreshed with
 * `gh auth refresh`, the other has to be regenerated where it was made.
 */
tokenSource: string | null, host: string | null, login: string | null, 
/**
 * As `gh` reports them, split on the commas it separates them with. Empty
 * for a token that carries no scopes at all, which is every fine-grained
 * personal access token — its permissions are on GitHub, not in here.
 */
scopes: Array<string>, 
/**
 * **`gh`'s own sentence where it found a credential and was refused**,
 * which is the state a reader is in when the token is there and wrong.
 */
error: string | null, };

/**
 * A goal, as the agent states one.
 *
 * **`status` is a `String` and not an enum**, the bargain every other reader here
 * makes: the agent's vocabulary is `active`, `paused`, `blocked`, `complete` and
 * `budget_limited` today, and a word added after this build must draw as itself
 * rather than fail the line that carried it. What this app *sends* is a closed set
 * — see [`GoalMove`] — because that half is this app's to shape.
 */
export type Goal = { goalId: string, objective: string, status: string, 
/**
 * Why the status is what it is, where the agent said so — its own sentence,
 * drawn as written.
 */
statusReason: string | null, tokensUsed: number, turnsUsed: number, 
/**
 * Absent where the goal was set without one, which is a goal that runs until
 * somebody stops it rather than forever.
 */
tokenBudget: number | null, 
/**
 * Wall-clock seconds the runtime has spent on it, which is the number a
 * reader watching a long goal actually feels. Ticks on its own, so the band
 * adds its own second-resolution counter while the goal is `active` rather
 * than repainting on a push that never comes.
 */
timeUsedSeconds: number, 
/**
 * What an `active` goal is parked on, where it is parked. `None` is the
 * ordinary "it is working" case.
 */
executionWait: ExecutionWait | null, 
/**
 * The last verifier's verdict, where the runtime keeps one — the only place
 * the *why* of a goal that has not finished lives.
 */
lastVerification: Verification | null, };

/**
 * The pushed goal, shaped for the webview.
 *
 * Carries *this* app's session id rather than the wire's, so the frontend routes
 * it into the session it already holds — mcode's own id lives on the index entry
 * and nowhere the listener reads.
 */
export type GoalEvent = { sessionId: string, goal: Goal | null, };

/**
 * What a control can ask a goal to do.
 *
 * **Two of the agent's five, and the split is who decides.** `blocked`,
 * `complete` and `budget_limited` are the agent's own verdicts on work it is
 * doing; a button for `complete` would let a reader tell the agent that a job it
 * is still on is finished, which is the one thing a goal exists to keep honest.
 */
export type GoalMove = "active" | "paused";

/**
 * Which agent runs a session.
 *
 * **Unknown spellings are kept, not refused.** `index.json` is a shared store
 * rewritten whole by whichever build writes last, so a value a newer build
 * wrote reaches an older one — and serde's default for an unrecognised variant
 * is to fail the *line*, which here is the whole file. One `"pi"` written by a
 * dev build made a released app read 256 sessions as none at all, with
 * `unknown variant \`pi\`` the only thing said about it.
 *
 * So this is the same bargain [`SessionIndexItem.unknown`] makes one level
 * out: carry what you cannot understand through untouched. [`Harness::Other`]
 * holds the original string and serializes it back verbatim, so an old build
 * reading and rewriting the index leaves a newer build's sessions exactly as it
 * found them. Storing a placeholder instead would parse fine and quietly
 * destroy the harness of every session it did not recognise, which is the
 * worse half of this failure rather than a lesser one.
 *
 * It is **not** in [`Harness::ALL`]: that is the set this build offers, and an
 * unknown one is not offerable. Nothing spawns for it either — see
 * [`Harness::names_a_cli`].
 *
 * [`SessionIndexItem.unknown`]: crate::store::SessionIndexItem
 */
export type Harness = "mcode";

export type HookPhase = "started" | "finished";

export type ImageRef = { path: string | null, url: string | null, mimeType: string | null, };

/**
 * An input the reader can pick in settings.
 */
export type InputDevice = { 
/**
 * Also the identity: devices are stored and matched by name.
 *
 * cpal offers an enumeration index too, and Handy persists that. It is the
 * wrong key — the order changes when a USB mic is unplugged, so a stored
 * index silently starts naming a different device.
 */
name: string, isDefault: boolean, };

/**
 * Which half of the install failed, and it is tagged because the two have
 * opposite cures: a swap that did not complete leaves nothing to open, so
 * pressing the button again is the answer, where a failed *relaunch* left the
 * new bundle on disk and only opening it finishes the job. Telling the reader
 * to quit and reopen for a swap that never landed sends them to do nothing.
 *
 * "Did not complete" is deliberately weaker than "changed nothing": the
 * plugin moves the old bundle to a temp backup before unpacking, and a final
 * rename that fails returns `Err` without putting it back. Narrow, upstream,
 * and not something to claim the opposite of in a comment.
 *
 * A tag rather than a sentence the frontend matches on, so rewording a message
 * cannot silently swap one cure for the other.
 */
export type InstallError = { "stage": "install", message: string, } | { "stage": "relaunch", message: string, };

/**
 * What the settings dialog draws. `None` is a tracker nobody has connected.
 */
export type IntegrationsView = { linear: TrackerAccount | null, };

/**
 * One row in a list, and everything a row draws.
 *
 * Distinct from [`IssueDetail`] rather than one type with empty fields: a list
 * read does not ask for descriptions or comments, and a struct that carries
 * them anyway hands the panel an issue whose body is silently missing.
 */
export type Issue = { tracker: IssueTracker, id: string, identifier: string, title: string, url: string, state: IssueState, priority: IssuePriority, assignee: IssuePerson | null, labels: Array<IssueLabel>, 
/**
 * Team key (`DRA`) — what the identifier is built from, so a row filtered
 * across teams still says which one it belongs to.
 */
team: string | null, project: string | null, updatedAt: string, };

/**
 * A file uploaded to an issue, fetched with the stored key.
 *
 * **The whole reason this command exists.** Linear's uploads live behind the
 * same auth the API does, so the `<img src>` in a description resolves to a
 * 401 and the webview draws its broken-image box — which reads as "hz cannot
 * show this" rather than "this needs a key". Fetching here and handing back a
 * `data:` URL is what makes an image in an issue an image on screen.
 *
 * Bytes rather than a signed URL because Linear issues none, and `data:`
 * rather than a local file because these are read once and thrown away.
 */
export type IssueAsset = { 
/**
 * `image/png`, `text/plain`… as the server reported it.
 */
mime: string, 
/**
 * `data:<mime>;base64,…`, ready to put in a `src` or an `href`.
 */
dataUrl: string, bytes: number, };

export type IssueComment = { author: IssuePerson, body: string, createdAt: string, url: string | null, };

/**
 * One issue, opened. The panel's read.
 */
export type IssueDetail = { 
/**
 * Markdown, as the tracker holds it. `None` for an issue nobody wrote one
 * for, which the panel says plainly rather than drawing an empty box.
 */
description: string | null, comments: Array<IssueComment>, 
/**
 * Every status this issue's own team offers, in workflow order — what the
 * header's status menu draws.
 *
 * On the detail rather than read by a command of its own, because it rides
 * the read the panel already makes: a menu that has to fetch before it can
 * open is a menu that opens empty. Per *team*, so an issue moved between
 * teams offers the states of wherever it now lives.
 */
states: Array<IssueState>, tracker: IssueTracker, id: string, identifier: string, title: string, url: string, state: IssueState, priority: IssuePriority, assignee: IssuePerson | null, labels: Array<IssueLabel>, 
/**
 * Team key (`DRA`) — what the identifier is built from, so a row filtered
 * across teams still says which one it belongs to.
 */
team: string | null, project: string | null, updatedAt: string, };

/**
 * The filter row's options, read once per connection rather than per keystroke.
 */
export type IssueFilters = { teams: Array<IssueGroup>, projects: Array<IssueGroup>, 
/**
 * Every team's workflow states, keyed by team **key** (`DRA`) — what a
 * row carries, where `teams` above is keyed by UUID.
 *
 * Here rather than on each issue because a workflow belongs to a team: one
 * answer serves every row that team owns, so the issues page's status menus
 * cost one read per connection instead of a copy per row.
 */
teamStates: { [key in string]: Array<IssueState> }, };

export type IssueGroup = { id: string, name: string, };

export type IssueLabel = { name: string, color: string, };

export type IssuePerson = { name: string, 
/**
 * `None` for an account with no picture, which the panel draws as an
 * initial rather than as a gap — same bargain the PR panel makes.
 */
avatar: string | null, };

/**
 * Linear's five levels, by name rather than by its `0..4` integer — where `0`
 * is *no* priority and therefore sorts nothing like a number.
 */
export type IssuePriority = "urgent" | "high" | "medium" | "low" | "none";

/**
 * What the issues page can narrow to, and what the picker asks with.
 */
export type IssueQuery = { 
/**
 * Free text. Matched against title and identifier; an empty query is the
 * resting state and lists rather than searches.
 */
text: string | null, scope: IssueScope, 
/**
 * Linear team id.
 */
teamId: string | null, projectId: string | null, 
/**
 * Which half of the workspace to read: the unfinished issues, or the done
 * and cancelled ones.
 *
 * Two reads rather than one flag that widens a single read, because the
 * settled half is most of a workspace and is nearly always dead weight —
 * so the page draws its groups collapsed and asks for them only when one
 * is opened. Splitting it here rather than filtering client-side is what
 * makes that possible: a read that never happens costs nothing, and the
 * two answers cache under separate keys.
 */
settled: boolean, };

/**
 * What a session records about an issue it is working on.
 *
 * Deliberately a *copy*, not a pointer: the title and the URL are what the
 * sidebar and the prompt block need, and re-reading the tracker to draw a row
 * would put a network call behind a session opening. It goes stale — a
 * retitled issue keeps the old words here until the panel reads it back — and
 * that is the right way round, since the alternative is a row that cannot be
 * drawn while the workspace is unreachable.
 */
export type IssueRef = { tracker: IssueTracker, 
/**
 * The tracker's own stable id, which survives a move between teams where
 * `identifier` does not.
 */
id: string, 
/**
 * What a person calls it: `DRA-53`.
 */
identifier: string, title: string, url: string, };

/**
 * Whose issues to list.
 *
 * The tracker's own two answers to "my issues", and a third for looking past
 * them. Deliberately not a pair of booleans: assigned *and* created is a
 * question nobody asks, and two flags can express it.
 */
export type IssueScope = "assigned" | "created" | "all";

export type IssueState = { 
/**
 * The tracker's own id. What a status write names — a state is addressed
 * by id and never by name, since two teams can both call one "In Review".
 */
id: string, name: string, kind: IssueStateKind, 
/**
 * The tracker's own colour, so a status reads the same here as it does in
 * the app the reader also has open.
 */
color: string, };

/**
 * Where an issue has got to, folded from the tracker's own vocabulary.
 *
 * Linear reports a workflow state's `type`, which is this set exactly — the
 * state's *name* is per-team prose ("In Review", "Shipping") and belongs on
 * screen, not in a match arm.
 */
export type IssueStateKind = "triage" | "backlog" | "unstarted" | "started" | "completed" | "canceled" | "other";

/**
 * Who tracks the issue. One variant today; it is on the wire and on disk so a
 * session linked to a Linear issue stays readable once there are two.
 */
export type IssueTracker = "linear";

/**
 * Why there is nothing to show.
 *
 * Typed for [`PrUnavailable`](crate::github::PrUnavailable)'s reason: the
 * frontend acts differently on each. `NotConnected` is the resting state of an
 * app nobody has connected — an empty state pointing at settings, never an
 * error — where `Unauthorized` means a key that has been revoked or rotated
 * and is the one the reader has to do something about.
 */
export type IssueUnavailable = { "kind": "not_connected" } | { "kind": "unauthorized" } | { "kind": "offline", "detail": string } | { "kind": "other", "detail": string };

/**
 * How a server talks, as the form on the other side spells it.
 *
 * **Flat, with the fields of both transports.** The form switches between them
 * and the fields follow it, so the shape it holds is one object with both; the
 * agent narrows this to its own union — a stdio server has no `url` — at the
 * boundary that owns that rule. Kept flat here too rather than mirrored as a Rust
 * enum: an enum would make this app the second place the rule lives, and two
 * copies of it is one copy that can be wrong.
 */
export type McpConfig = { transport: string, command: string | null, args: Array<string> | null, env: { [key in string]: string } | null, url: string | null, headers: { [key in string]: string } | null, timeoutMs: number | null, description: string | null, };

/**
 * Shared with the harness parsers rather than duplicated — the wire shape
 * matches, so they deserialize straight into this.
 */
export type McpServer = { name: string, 
/**
 * Free-form: `connected`, `pending`, `needs-auth` observed, set undocumented.
 */
status: string, };

/**
 * One server with its whole configuration — the read the edit form opens on.
 */
export type McpServerDetail = { name: string, enabled: boolean, config: McpConfig, };

/**
 * What a connection test answered.
 *
 * **`success: false` with a code rather than an error.** A server that saves
 * cleanly and cannot be reached is the ordinary failure here, and the code is what
 * tells "the command is not installed" from "the handshake failed" — two different
 * things for the reader to go and do.
 */
export type McpTestResult = { success: boolean, toolCount: number | null, 
/**
 * What the server offers, empty on a failure.
 *
 * **Already in the agent's hand when it counted them**, so this is not a second
 * connection — it is the same answer with the list kept instead of thrown away.
 * Defaulted, because a failure has no tools to speak of and should read as none
 * rather than as a reply this build could not parse.
 */
tools: Array<McpTool>, errorCode: string | null, errorMessage: string | null, };

/**
 * One tool a server offers.
 *
 * The name and the sentence the server wrote about it, and **not** its input
 * schema: a schema per tool is a payload nothing drawing a list reads, and the
 * reader who wants one is asking the agent, not this screen.
 */
export type McpTool = { name: string, description: string | null, };

/**
 * How to land it. The three GitHub offers; the flag each maps to is `gh`'s.
 */
export type MergeMethod = "merge" | "squash" | "rebase";

/**
 * Who relayed a prompt into this session, for a `user_message` the user did
 * not type.
 *
 * Both fields are needed and neither substitutes for the other: the title is
 * what the reader recognizes — it is what the sidebar shows — and the id is
 * what the transcript navigates to when they click it.
 *
 * Persisted, unlike most of what the app synthesizes: the transcript is
 * replayed from the log, so attribution that lived only in memory would be
 * gone on the next open.
 */
export type MessageSender = { sessionId: string, title: string, };

export type Model = { 
/**
 * What an index entry records.
 */
id: ModelId, label: string, 
/**
 * Empty means the model has no effort levels. The CLI tolerates `--effort`
 * on such a model and ignores it, so this drives the UI and keeps the
 * persisted value honest rather than preventing a crash.
 */
efforts: Array<Effort>, defaultEffort: Effort | null, 
/**
 * The model without its variant, as the wire spells it (`m:<provider>:<model>`,
 * no `:v:` tail) — the key a picker groups rows by. Empty where the id is not
 * a wire ref at all, which reads as "do not group".
 *
 * mcode lists **one choice per variant**, so `minimax-m3` arrives as a single
 * row named `minimax-m3 · thinking` and a model with two variants arrives as
 * two rows. Grouping them here rather than in the frontend keeps the parse
 * where the wire format is: `:v:` is ACP's, not the picker's.
 */
baseId: string, 
/**
 * The window the agent states for this model, and the budget it may reply
 * with — `None` where the agent said nothing, which is what a row draws as
 * its fallback rather than as a fact.
 */
contextWindow: number | null, maxTokens: number | null, 
/**
 * The variant's own name (`thinking`, `fast`), or empty where the id names
 * none. Drawn as the row's second control rather than glued to the model's
 * name — which is what `label` used to carry.
 */
variant: string, 
/**
 * What `--model` receives, where that differs from the persisted id.
 *
 * The two genuinely differ — `gpt56_sol` on disk, `gpt-5.6-sol` on the
 * command line — which is why the enum this replaces needed an `as_arg`
 * table at all. That table, moved onto the row it describes, so a
 * discovered model carries its own alias instead of needing an arm here.
 */
arg: string, 
/**
 * Who serves it, where the harness has more than one.
 *
 * Empty for the two single-vendor harnesses, which is what the picker
 * reads as "do not group". pi's ids are `provider/model`, so the split is
 * its own and made once, in `harness/pi/models.rs`.
 */
provider: string, 
/**
 * Whether the composer's image tray can send to this model at all.
 *
 * A real one says no: `gpt-5.3-codex-spark` reports `input: ["text"]`, and
 * a tray that offers to attach a screenshot to it fails at the send with a
 * sentence the reader cannot act on.
 */
acceptsImages: boolean, 
/**
 * Drawn under the picker's "More models" submenu rather than at the top
 * level, and skipped by Shift+Tab.
 *
 * The chord cycles the list in order, which only works while the list is
 * short — so this is what keeps it short as pinned and older models are
 * added. A reader who picks one from the submenu keeps it: the flag
 * decides where a row is *drawn*, never what may be run.
 */
secondary: boolean, 
/**
 * Whether this model has a fast mode to ask for.
 *
 * Per *model*, never per family, because both CLIs that have one answer it
 * that way: Claude Code offers fast mode on Opus alone, and Codex reports
 * `serviceTiers` row by row. A row wrongly marked here draws a switch that
 * silently changes nothing — Codex accepts an unknown `serviceTier` with
 * no error at all — so it follows the wire wherever the wire answers.
 */
supportsFast: boolean, };

/**
 * What an index entry records for a session's model.
 *
 * A newtype over the string it has always serialized as. The closed enum this
 * replaces was a validation layer wearing a type's clothes: validity is
 * [`find_model`]'s question, since only the model table knows whether an id
 * names something this build can run — and a harness whose model list is
 * answered at runtime has ids no enum written here could hold.
 *
 * An untagged `Known(..) | Named(String)` enum was the first proposal and has
 * a bug in it. Two spellings of one value would exist, identical on the wire
 * and unequal under a derived `PartialEq`, and that equality is what decides
 * whether [`crate::session`] replaces a live child or sends `set_model`. A
 * model reaching one side through the index and the other through the composer
 * would respawn a running session, silently and unreproducibly.
 */
export type ModelId = string;

/**
 * What one model has consumed **for the session so far** — cumulative and
 * monotonic across turns, not a per-turn figure.
 *
 * That is the whole reason it is carried and persisted. [`Usage`]'s own counts
 * are the harness's per-turn sum over every main-thread message, which double
 * counts a context re-read once per tool call and so describes neither the turn
 * nor the context. Here a turn's real consumption is the difference between
 * consecutive readings.
 *
 * Every field is optional and the harness's own map is left untyped upstream:
 * this rides `turn_completed`, and a `result` line that fails to parse strands
 * the session on `in_progress`. A shape we don't recognize must cost this
 * struct a field, never the line.
 */
export type ModelUsage = { 
/**
 * The harness's own key — a dated id (`claude-haiku-4-5-20251001`), not the
 * alias a session was started with.
 */
model: string, inputTokens: number | null, outputTokens: number | null, cachedInputTokens: number | null, cacheWriteTokens: number | null, webSearchRequests: number | null, costUsd: number | null, 
/**
 * This model's context window. Also what the composer's gauge measures
 * against — see `context_window` in the Claude Code mapper.
 */
contextWindow: number | null, maxOutputTokens: number | null, };

/**
 * What the composer's add form collects.
 */
export type NewProvider = { name: string, baseUrl: string, 
/**
 * `anthropic-messages`, `openai-completions` or `openai-responses`.
 */
apiFormat: string, 
/**
 * One id per row, in the order the reader typed them. **Empty is the
 * ordinary case**: it means "ask the provider", and [`add`] fills it in
 * from [`discover`] before the CLI is called.
 */
models: Array<string>, apiKey: string, 
/**
 * Test the first model, then save and select it as the default.
 */
makeDefault: boolean, };

export type PermissionBehavior = "allow" | "deny";

/**
 * What the CLI *reports* in `system/init`, which is a wider set than it
 * accepts: `default` names the harness's own prompting stance, and
 * `--permission-mode` rejects that name while offering `manual` for the same
 * thing. Kept separate from [`ApprovalPolicy`] rather than remapped, so a
 * round trip can't quietly turn one into the other.
 */
export type PermissionMode = "default" | "plan" | "manual" | "acceptEdits" | "auto" | "dontAsk" | "bypassPermissions";

/**
 * One answer the user can give to a [permission
 * request](AgentEventPayload::PermissionRequested).
 *
 * Deliberately carries no wire payload. The standing rule an option would
 * apply is the harness's to compose and the harness's to send, so the app
 * replies with [`id`](Self::id) alone and the harness resolves it — which keeps
 * a rule that grants more than it appears to from ever being assembled on the
 * UI side.
 */
export type PermissionOption = { 
/**
 * Unique within its request, and the whole of what the app sends back.
 */
id: string, label: string, kind: PermissionOptionKind, 
/**
 * Whether picking this lets the call run. Both `Deny` kinds carry
 * [`Deny`](PermissionBehavior::Deny); everything else allows.
 */
behavior: PermissionBehavior, };

/**
 * What an option *does*, for a renderer that wants to group or order them.
 * The set is closed on purpose: an unmappable suggestion is dropped rather
 * than shown as a button whose effect can't be described.
 */
export type PermissionOptionKind = "once" | "always_rule" | "always_directory" | "switch_mode" | "deny";

/**
 * One Agent this machine holds — a definition a Session is started *under*.
 *
 * **Not a Session and not a subagent.** Three are built in (`explore`,
 * `worker`, `verifier`) and the reader may write their own; a `task` call names
 * one in its `agent_name`, which is why a screen for them belongs beside the
 * Tools the agent can reach.
 */
export type PluginAgent = { 
/**
 * The store's own key for it, and what a write addresses.
 */
name: string, 
/**
 * What the row is called on screen — the agent's own label where it has one.
 */
displayName: string, description: string | null, 
/**
 * A built-in portrait marker (`mavis-agent-avatar://default/v1/N`) or an
 * image, as stored. The frontend decides which of the two it is drawing.
 */
avatar: string | null, 
/**
 * The role it plays, in the agent's own words.
 */
agentRole: string, 
/**
 * Where it came from — `builtin`, `manual`, and whatever the agent adds
 * later. Carried verbatim rather than mapped onto an enum of ours, for the
 * reason [`PluginSkill::source_kind`] gives.
 */
creationSource: string, 
/**
 * Whether the agent ships it. Derived here from `creation_source` so the
 * screen files built-ins apart without keeping its own list of names — a
 * role added after this build files itself correctly.
 */
builtin: boolean, };

/**
 * One MCP server this machine has written down, as a row.
 *
 * **The reader's own store, not what a session can reach.** The agent keeps two
 * MCP lists: the other one is what a *session* can reach — built-ins, the
 * project's own file, the session's own set — and a server switched off is not in
 * it at all. A screen with switches in it needs this one, because otherwise
 * switching a server off would take its own row away.
 *
 * **No configuration rides here.** `env` and `headers` hold credentials, and a
 * listing drawn to show names has no business carrying every secret on the
 * machine — [`McpServerDetail`] is the one read that does, and it is asked for one
 * server at a time.
 */
export type PluginMcpServer = { name: string, enabled: boolean, 
/**
 * The agent's own word for how it talks: `stdio`, `http`, `streamable-http` or
 * `sse`. Carried verbatim rather than mapped onto an enum of ours, for the
 * reason [`PluginSkill::source_kind`] gives — a transport added after this
 * build should draw as itself.
 */
transport: string, description: string | null, 
/**
 * The command for a stdio server, or the URL for a remote one — and never the
 * arguments, the environment or the headers.
 */
endpoint: string | null, };

/**
 * One Skill.
 */
export type PluginSkill = { 
/**
 * The registry's own name for it, and what a switch is addressed to.
 */
name: string, 
/**
 * What the row is called on screen — the agent's own label where it has one.
 */
displayName: string, description: string, 
/**
 * Whether the model is told about it. **A Skill switched off keeps its row**,
 * which is the whole reason this screen can switch one back on.
 */
enabled: boolean, 
/**
 * Where it came from, in the agent's own words — `user`, `builtin-global`,
 * `builtin-agent`. Carried verbatim rather than mapped onto an enum of ours,
 * for the reason [`ContextComponent`](crate::context::ContextComponent)
 * gives: a kind added after this build should draw as itself rather than as
 * nothing.
 */
sourceKind: string | null, 
/**
 * The registry's own key for it. Handed back on a switch so a Skill renamed
 * between the read and the press still moves the right one.
 */
locationUri: string | null, };

export type PrCheck = { name: string, state: CheckState, 
/**
 * Where the log lives. `None` for a check that reports no link.
 */
url: string | null, 
/**
 * The Actions workflow this run belongs to, when it is one — several
 * workflows can contribute checks of the same name.
 */
workflow: string | null, 
/**
 * The mark of whoever reports this check — Vercel's logo on a Vercel
 * check. It is what makes a list of check names scannable without reading
 * them, and it cannot be built from the login: see [`QUERY`].
 */
avatar: string | null, };

/**
 * What CI on the tip commit has to say, cut to the two things a row can show.
 *
 * Passing is folded in with "no checks at all" on purpose: a row that says
 * nothing is a row with nothing to do, and marking every green branch green a
 * second time makes the mark that *does* need reading harder to find. So this
 * is a three-way, not the rollup's five-way — `SUCCESS` and an absent rollup
 * both reach the reader as [`PrChecksState::Clear`].
 */
export type PrChecksState = "RUNNING" | "FAILING" | "CLEAR";

export type PrComment = { author: string, 
/**
 * The commenter's picture. `None` for an account that has none, which the
 * panel draws as their initial rather than as a gap.
 */
avatar: string | null, body: string, createdAt: string, url: string, kind: CommentKind, 
/**
 * The file an inline review comment hangs on — `path:line`, or the path
 * alone once GitHub has forgotten which line it pointed at. `None` for
 * everything on the conversation timeline, which hangs on nothing.
 */
path: string | null, 
/**
 * Whether the thread has been settled. False for every row that is not a
 * thread, since only a review thread can be resolved.
 */
resolved: boolean, 
/**
 * The rest of the thread, oldest first. Only an inline comment carries
 * any: a PR's own conversation is flat, so a reply is either part of a
 * review thread or it is a new comment.
 */
replies: Array<PrComment>, 
/**
 * GitHub's node id for the review thread this comment opens, on the one
 * comment that does open one.
 *
 * **Carried so the panel can answer a thread and settle one.** Both are
 * GraphQL mutations keyed on this id and on nothing else — not on the PR
 * number, not on the path, not on the line, all three of which a reply or a
 * resolve has no way to address. `None` everywhere that is not a thread
 * root, which is every timeline row.
 */
threadId: string | null, };

/**
 * One commit on the branch, cut down to what a row draws.
 *
 * Not the same shape as the commits panel's `Commit`, which reads a working
 * tree's history with `git` and carries a full body and tree. This is
 * GitHub's, reached with `gh`, and the pane wants a line per commit.
 */
export type PrCommit = { 
/**
 * The full sha, which is what the row's own link would need.
 */
oid: string, 
/**
 * GitHub's own abbreviation, so the row shows the length GitHub shows.
 */
shortOid: string, 
/**
 * The first line of the message and only the first — a full body here
 * would be one commit's essay among a list of one-liners.
 */
headline: string, committedAt: string, 
/**
 * The name git was configured with, which is the only thing a commit
 * *always* has. Attribution to an account is below, and can be missing.
 */
author: string, 
/**
 * The account GitHub credits it to, where it can attribute one — an email
 * that matches no account resolves to the name alone.
 */
login: string | null, avatar: string | null, };

/**
 * One file a pull request touches.
 */
export type PrFile = { 
/**
 * Repo-relative, the way every path in this app is.
 */
path: string, additions: number, deletions: number, 
/**
 * `ADDED`, `MODIFIED`, `DELETED`, `RENAMED` or `COPIED`, GitHub's own
 * word, carried through untranslated — the panel draws a glyph for the
 * three it knows and nothing for the rest.
 */
changeType: string, };

/**
 * One label, as a row draws it: the name, and the colour so the dot beside it
 * is the one GitHub shows rather than a shade this app invented.
 */
export type PrLabel = { name: string, 
/**
 * Six hex digits without the `#`, or `None` for a label with no colour set.
 */
color: string | null, };

/**
 * One row of the pull-request page: what a *list* needs, and nothing that only
 * a detail read can answer.
 *
 * Deliberately not [`PullRequest`]. A page shows fifty rows and a detail pane
 * shows one: asking for the full shape fifty times is fifty comment trees and
 * fifty check lists nobody scrolls. What a row cannot answer — the checks
 * themselves, the conversation, the threads — the detail read answers, and the
 * page uses the same `prs_for_branch` for it that the session's own tab does.
 */
export type PrListItem = { number: number, title: string, url: string, 
/**
 * `OPEN`, `CLOSED` or `MERGED`, GitHub's own word.
 */
state: string, isDraft: boolean, author: string, avatar: string | null, headRefName: string, baseRefName: string, updatedAt: string, 
/**
 * When it was opened. The list can be ordered by age, and `updatedAt` cannot
 * answer that: a year-old pull request touched this morning is the newest by
 * one and the oldest by the other.
 */
createdAt: string, additions: number, deletions: number, changedFiles: number, reviewDecision: string | null, mergeable: string, mergeStateStatus: string, 
/**
 * The tip commit's checks, folded to one word — the same fold the sidebar's
 * marks use, for the same reason: a row has space for running or failing,
 * not for fifty contexts.
 */
checksState: PrChecksState, 
/**
 * Everyone asked to review it — people by login, teams by slug.
 *
 * This is what the page's "waiting on you" grouping asks about, and it is
 * why the grouping is done here rather than with three `gh` calls: one
 * listing plus the viewer's own login (cached for the process) answers
 * "mine", "waiting on me" and "everything else" without a spawn per group.
 */
reviewRequests: Array<string>, 
/**
 * What the repository has filed it under.
 *
 * Carried because the page's own filter menu wants them and a label is the
 * one narrowing GitHub cannot answer for: `--label` exists on `gh pr list`,
 * and a filter that re-read the host on every tick would be a spawn per
 * click against labels the listing already holds.
 */
labels: Array<PrLabel>, };

/**
 * The rows and who is asking.
 */
export type PrListPage = { items: Array<PrListItem>, 
/**
 * The signed-in account, or `None` where `gh` would not say — in which case
 * nothing is filed under the reader's own name and every row lands under
 * Others, which is the honest answer rather than a guess.
 */
viewer: string | null, };

/**
 * Which pull requests a listing wants.
 *
 * GitHub's three states plus "all", because a page that only ever showed open
 * ones could not answer "did this land?" — the question the panel exists for,
 * asked about work that is not on screen.
 */
export type PrListState = "all" | "open" | "closed" | "merged";

/**
 * One pull request, cut down to what a sidebar row can draw.
 *
 * Deliberately not a `PullRequest`: the row says "this branch has a PR, and
 * what became of it" and nothing else, so carrying checks, comments and review
 * threads for every session in the list would be payload nobody reads.
 */
export type PrMark = { number: number, 
/**
 * The branch it was opened from — what the caller matches a session by.
 */
headRefName: string, isDraft: boolean, state: PrMarkState, checksState: PrChecksState, 
/**
 * Enough of the panel's merge fields to answer "can this land now", which
 * the sidebar itself draws nothing from — the notice for a pull request
 * turning ready does, and this is the only read that runs for a session
 * nobody is looking at. The panel's query is gated on its own tab being
 * on screen, which is precisely when there is nothing to announce.
 *
 * `None` on the merged half, where they are not asked for. The frontend
 * reads that as *unknown* rather than as ready — see `mergeVerdict`.
 */
mergeable: string | null, mergeStateStatus: string | null, };

/**
 * Which of the two connections a mark came from.
 *
 * Not parsed off the wire: [`QUERY_MARKS`] asks each state in its own aliased
 * connection, so the connection *is* the answer and a `state` field would be a
 * second copy of it free to disagree. Only the two states the sidebar draws —
 * closed-without-merging is not asked for.
 */
export type PrMarkState = "OPEN" | "MERGED";

/**
 * Why there is nothing to show, when the reason is not "this branch has no PR".
 *
 * Typed rather than a string because the frontend acts differently on each:
 * a missing `gh` hides the tab outright — the app has no business claiming a
 * GitHub feature on a machine with no GitHub CLI — while a `gh` that is merely
 * logged out keeps the tab and says so, since someone who installed it clearly
 * works with GitHub and the fix is one command.
 */
export type PrUnavailable = { "kind": "no_cli" } | { "kind": "not_authenticated" } | { "kind": "no_remote" } | { "kind": "missing_permission" } | { "kind": "other", "detail": string };

/**
 * Every preference the frontend owns, as the file holds them.
 *
 * One payload for all of them, read once before the first render: a command
 * per key would be a round trip per picker to draw the app. **Every field is
 * `None` where the file says nothing**, which is what a build that has just
 * moved these out of the webview's store reads to tell a key the file already
 * answers for from one still to adopt; a field that is present has been
 * answered for, whether or not the frontend would read the same value back.
 *
 * Not [`AppSettings`] itself: that carries the install id and the Linear
 * account, and neither is the webview's business.
 */
export type Preferences = { 
/**
 * See [`AppSettings::composer_prefs`].
 */
composerPrefs: JsonValue | null, 
/**
 * See [`AppSettings::hidden_models`].
 */
hiddenModels: Array<string> | null, 
/**
 * See [`AppSettings::shortcuts`].
 */
shortcuts: JsonValue | null, 
/**
 * See [`AppSettings::update_channel`].
 */
updateChannel: UpdateChannel | null, 
/**
 * See [`AppSettings::open_with`].
 */
openWith: string | null, 
/**
 * See [`AppSettings::open_file_with`].
 */
openFileWith: string | null, 
/**
 * See [`AppSettings::run_in_terminal`].
 */
runInTerminal: string | null, 
/**
 * See [`AppSettings::space`].
 */
space: string | null, 
/**
 * See [`AppSettings::spaces`].
 */
spaces: Array<string> | null, };

/**
 * One preference to change, and what to change it to.
 *
 * **A patch names one preference, and that is what makes an update partial**:
 * the command takes a batch of these, and nothing a batch does not name is
 * touched. `None` clears what a patch does name — the active space going away
 * when the last thing filed under it is renamed out, which has to be sayable,
 * since "no space" is not a value a space can hold.
 *
 * Tagged rather than a struct of optional fields so that a name that does not
 * exist is an error rather than a field that silently writes nothing, and so
 * that the value each one carries is typed where it is declared.
 */
export type PreferencesPatch = { "field": "composerPrefs", "value": JsonValue | null } | { "field": "hiddenModels", "value": Array<string> | null } | { "field": "shortcuts", "value": JsonValue | null } | { "field": "updateChannel", "value": UpdateChannel | null } | { "field": "openWith", "value": string | null } | { "field": "openFileWith", "value": string | null } | { "field": "runInTerminal", "value": string | null } | { "field": "space", "value": string | null } | { "field": "spaces", "value": Array<string> | null };

/**
 * A directory the user attached, and the root a session runs in. Distinct from
 * [`crate::store::SessionIndexItem::project_path`], which records where a
 * session *did* run — a project can be detached without rewriting history.
 */
export type Project = { 
/**
 * Canonicalized at attach time, so this is the only spelling of the path
 * that ever reaches the index or the sidebar's grouping key.
 */
path: string, 
/**
 * Folder name as of attaching. Cached so a project whose directory was
 * since renamed or removed still has a label.
 */
name: string, 
/**
 * Which space the project belongs to, or `None` for one nobody filed.
 * The tag is the whole record of a space — there is no spaces file — so a
 * space exists exactly while some project names it, and the last project
 * leaving takes it with them.
 */
space: string | null, 
/**
 * Doubles as the sort key and the "which project was last open" answer:
 * selecting a project *is* what makes it most recent, so a separate
 * `last_selected` pointer would be a second place to keep the same fact.
 */
lastSelected: string, };

/**
 * One row of `provider list --json`.
 */
export type Provider = { providerId: string, name: string, 
/**
 * `minimax-oauth`, `minimax-api-key` or `custom`.
 */
kind: string, 
/**
 * The one the agent draws its models from. More than one may be enabled.
 */
active: boolean, enabled: boolean, 
/**
 * hz may list it and may not edit it — the managed account's own entry.
 */
readOnly: boolean, 
/**
 * **A bool, never the key**: the CLI reports whether one is stored, and
 * the app neither reads nor holds the secret after handing it over.
 */
hasApiKey: boolean, 
/**
 * The gateway's URL, as the agent itself reports it. Drawn on the
 * connected row so a reader can tell two entries apart without opening
 * anything, and absent on a provider the agent has no URL for.
 */
baseUrl?: string | null, 
/**
 * Which wire it speaks — `openai-completions`, `anthropic-messages` or
 * `openai-responses`. The same fact the connect row states before the key
 * is typed, read back off what was actually written.
 */
apiFormat?: string | null, 
/**
 * **Masked by the CLI, and never by this app.** `sk-q****CXTE` is the
 * agent's own redaction of the key it holds; the secret itself does not
 * cross back, and this is here for the one thing four characters can
 * answer — whether the key on this row is the one just pasted.
 */
maskedApiKey?: string | null, models: Array<ProviderModel>, };

/**
 * One row of a provider's `models` — **an object, not an id.**
 *
 * Read as a bare string this parses to nothing on a provider that has any
 * model at all, and takes the whole `provider list` down with it: the list is
 * one JSON value, so one unreadable row is every row the reader loses. The
 * gateway's own list endpoint has the same shape, which is why [`discover`]
 * reads `id` off it the same way.
 */
export type ProviderModel = { modelId: string, 
/**
 * The provider's own label, when it offers one. Usually absent.
 */
displayName?: string | null, 
/**
 * The default this provider's first model is pinned to, if any.
 */
selected: boolean, 
/**
 * The context window the agent will run this model at, where the provider
 * entry records one.
 *
 * **Absent is the state worth drawing, and it is not zero.** A model's
 * window is decided in three steps and this is the first: what this entry
 * records, then what the catalog the agent ships says for that model, then
 * `BYOK_FALLBACK_MODEL_LIMITS` in `model-resolver-byok.ts` (**200_000**
 * context, **16_384** output). So a gateway's own statement is written
 * here, and a gateway that states none is deliberately left absent — an
 * absent entry lets the catalog answer, where a copy of it taken once
 * would be believed long after the catalog moved. Only a model neither
 * names reaches the fallback, and that is the row drawn `200k default`
 * (`lib/providerLimits.ts` is where this build keeps the copy).
 */
contextLimit?: number | null, 
/**
 * The reply budget this model is pinned to, or absent for the same reason
 * and with the same fallback (`16k default`).
 */
maxOutputTokens?: number | null, };

/**
 * A gateway the agent already knows how to talk to, ready to be filled in with
 * a key.
 *
 * **The CLI's own wiring, not a guess.** OpenCode Go is special-cased inside
 * this agent: `packages/shared/opencode-go-headers.ts` recognises
 * `https://opencode.ai/zen/go`, stamps an `x-opencode-session` header on every
 * request and routes inference **by conversation** — which is why pointing a
 * provider at that URL is all "native support" means, and why the URL and the
 * dialect below are the ones that answer. Read off a working install rather
 * than from documentation.
 *
 * A preset only saves typing: what lands on disk is a `custom_provider` like
 * any other, and the manual form can still write every one of its fields. This
 * shape is what the reader sees when they pick a preset, and it is deliberately
 * two lines of text and a key — everything else is a fact the app holds, and
 * fields nobody is meant to touch invite touching.
 */
export type ProviderPreset = { 
/**
 * A stable slug for the gateway, and the only thing the view keys its
 * mark off. Not the name, because the name is copy and copy moves.
 */
id: string, 
/**
 * What the reader sees, and what the CLI `name`s the provider.
 */
name: string, baseUrl: string, 
/**
 * `openai-completions` here, which is the dialect this gateway speaks —
 * the CLI's own default for `provider add` is `anthropic-messages`, so
 * this is the field a reader would most often get wrong by hand.
 */
apiFormat: string, 
/**
 * Left empty on purpose, and empty is not "no models": [`add`] asks the
 * provider's own list endpoint and registers everything it serves. Naming
 * two ids would offer a reader a fraction of what they paid for.
 */
models: Array<string>, 
/**
 * One line about what the reader is signing up for, drawn under the name.
 */
note: string, };

export type PullRequest = { number: number, title: string, url: string, 
/**
 * `OPEN`, `CLOSED` or `MERGED`, carried through as GitHub's own word.
 */
state: string, isDraft: boolean, author: string, baseRefName: string, headRefName: string, 
/**
 * Whether that branch is still on the remote. `headRefName` survives the
 * branch itself — a merged PR keeps naming the branch it came from — so
 * the name cannot answer this and `headRef` going null is what does.
 */
headRefExists: boolean, 
/**
 * Whether the head branch lives in a fork rather than in this repo.
 *
 * `head_ref_name` is bare either way — a PR from `alice/hz:feature`
 * reports `feature` — so the name cannot be told apart from a branch of
 * our own, and joining it to this repo's slug addresses a *different*
 * branch that merely shares its name. Unknown reads as `true`, because
 * the only thing this gates is a deletion.
 */
isCrossRepository: boolean, 
/**
 * `MERGEABLE`, `CONFLICTING`, or `UNKNOWN` while GitHub is still working
 * the merge out — which it starts doing lazily, on being asked.
 */
mergeable: string, 
/**
 * The finer answer: `CLEAN`, `BLOCKED`, `BEHIND`, `DIRTY`, `UNSTABLE`,
 * `DRAFT`, `HAS_HOOKS`, `UNKNOWN`.
 */
mergeStateStatus: string, 
/**
 * `APPROVED`, `CHANGES_REQUESTED`, `REVIEW_REQUIRED`. `None` where the
 * repo requires no review, which `gh` reports as an empty string.
 */
reviewDecision: string | null, checks: Array<PrCheck>, 
/**
 * What the author wrote, as markdown. Empty is ordinary — plenty of pull
 * requests are a title and a diff.
 *
 * Rendered now, having been deliberately left out when the pane was a list
 * of *states*: it is the longest thing here and it pushed the checks below
 * the fold. Read against the sections around it — the files, the commits —
 * it is the one part of a pull request that says why any of it changed,
 * and the pane has somewhere to put it.
 */
body: string, 
/**
 * What the repository has filed it under, with their colours.
 */
labels: Array<PrLabel>, 
/**
 * Every file the change touches, with its own line counts.
 *
 * `changedFiles` is the count and this is the list, so the header can say
 * "12 files" while the section draws them. Capped at a hundred by the
 * query — past that the section says so rather than pretending.
 */
files: Array<PrFile>, 
/**
 * The commits on the branch, newest last — GitHub's own order, which is
 * how the reviewer above them reads them.
 */
commits: Array<PrCommit>, 
/**
 * Comments, reviews and inline threads in one list, oldest first — the
 * order GitHub reads them in, and the only order in which a bot's reply to
 * a review makes sense. A thread is one entry carrying its own replies.
 */
comments: Array<PrComment>, 
/**
 * Lines added and removed across the whole PR, and how many files moved.
 * The same figures the changes panel shows for a turn, for the same
 * reason: a row naming a PR says nothing about how much of one it is.
 */
additions: number, deletions: number, changedFiles: number, updatedAt: string, };

/**
 * One question from a [`QuestionsAsked`](AgentEventPayload::QuestionsAsked).
 *
 * [`id`](Self::id) is the step the agent matches the answer on, and what the
 * reply is keyed by. [`question`](Self::question) is only the text the reader
 * reads — two steps that happen to word it the same are still two steps.
 */
export type Question = { 
/**
 * The agent's own step id. Opaque here, and the key the answer goes back
 * under.
 */
id: string, question: string, 
/**
 * A short chip label for the question — "Indentation", "Auth method".
 *
 * No ACP elicitation carries one, so the chip falls back to the step's
 * ordinal; a harness that ships one gets it drawn.
 */
header: string | null, 
/**
 * Whether the agent refuses a reply that leaves this step out, which is
 * what hides the card's `Skip`.
 */
required: boolean, 
/**
 * Whether several options may be picked, in which case the answer carries
 * a value per option rather than one.
 */
multiSelect: boolean, 
/**
 * Two to four, per the tool's own schema. Never exhaustive: the harness
 * promises the user a free-text box alongside them, and instructs the model
 * not to offer an "Other" option because of it — so a renderer that shows
 * only these takes an answer away.
 */
options: Array<QuestionOption>, 
/**
 * Whether a typed answer beside [`options`](Self::options) is one the asker
 * can take. True for a step the agent allocated an other-field to, and for
 * a step that is nothing but a box.
 */
freeText: boolean, 
/**
 * The agent's own wording for the typed answer's box, off the other-field
 * it allocated. `None` means the card picks its own.
 */
otherPlaceholder: string | null, };

export type QuestionOption = { 
/**
 * What travels back as the answer, and what the agent matches the option
 * on.
 */
value: string, 
/**
 * What the user reads and picks.
 */
label: string, description: string | null, 
/**
 * Markdown the harness expects shown in a monospace box. Single-select
 * questions only.
 */
preview: string | null, };

/**
 * A prompt typed while a turn was running, held here until the turn reaches a
 * point where handing it to the CLI costs nothing.
 *
 * It is *not* persisted while it waits, and that is what makes cancelling it
 * clean: the log is append-only, so a queued message written on arrival could
 * only be retracted with a tombstone event. Held here instead, a cancel leaves
 * no trace at all. Nothing is lost by waiting — the flush persists it, and the
 * only window where it exists solely in memory is one the user is still
 * allowed to take it back from.
 */
export type QueuedMessage = { id: string, sessionId: string, 
/**
 * The raw prompt. Attachments are resolved at flush rather than now, so
 * what the composer gets back on a cancel is what the user typed.
 */
text: string, attachmentPaths: Array<string>, 
/**
 * Held with the prompt rather than looked up at flush: a relayed message
 * can wait out a long turn, and the sending session may be renamed or
 * deleted before the boundary that delivers it.
 */
from: MessageSender | null, 
/**
 * Resolved when the prompt was typed, not at flush, for `from`'s reason:
 * a held prompt can wait out a long turn, and re-reading the tracker at
 * the boundary would put a network call — and its failure — inside the
 * flush.
 */
issues: Array<IssueRef>, 
/**
 * The reader's clock at the press, carried through the wait rather than
 * read at the flush. A held prompt can wait out a whole turn, and the one
 * it opens is timed from the press — the boundary that released it is not
 * something the reader did.
 */
sentAt: string | null, };

export type RateLimit = { usedPercent: number | null, windowMinutes: number | null, 
/**
 * RFC3339, normalized from whatever the harness reports.
 */
resetsAt: string | null, planType: string | null, };

/**
 * One git repository a project root holds, with the little the composer's
 * repository control needs to draw a row.
 */
export type RepoSummary = { 
/**
 * Absolute, and spelled the way `repos_under` was handed it — this is what
 * becomes a session's `cwd`.
 */
path: string, 
/**
 * The directory's own name, which is what a row says: a workspace holds
 * repositories, and each one is named by its folder.
 */
name: string, 
/**
 * The checked-out branch. `None` on a detached HEAD.
 */
branch: string | null, 
/**
 * Uncommitted paths, so a row can say which repository is mid-work.
 */
dirty: number, };

/**
 * What the reviewer decided.
 *
 * GitHub's own three, and they are not interchangeable: approving a PR and
 * leaving a comment on it are different acts in the repo's history, and a
 * "request changes" blocks the merge where a comment does not.
 */
export type ReviewVerdict = "approve" | "request_changes" | "comment";

/**
 * What a save did. `Stale` is not an error: the file moved under the reader,
 * so their text is still in the editor and theirs to force through.
 */
export type SaveOutcome = "saved" | "stale";

/**
 * What a send did. The two fields are mutually exclusive in practice — a
 * session being created cannot already be running a turn — but they answer
 * different questions and the frontend acts on each separately.
 */
export type SendOutcome = { 
/**
 * `Some` only when this send created the session.
 */
snapshot: SessionSnapshot | null, 
/**
 * `Some` when a turn was already running, so the prompt is held rather
 * than sent. The frontend draws it as pending and can still take it back.
 */
queued: QueuedMessage | null, 
/**
 * Every issue the session is linked to now, as written.
 *
 * Answered on **every** path — created, live, queued and resumed — because
 * a `#DRA-53` is expanded and recorded on every one of them, and the
 * frontend has no other way to learn what a prompt just linked. Without it
 * a tag typed into an existing session persisted in Rust and reached the
 * panel only on a reselect or a restart: the Issue tab went on drawing the
 * session's old links while the index on disk held the new ones.
 *
 * The whole list rather than what this send added, for [`store::
 * link_session_issue`]'s reason — re-tagging *replaces* an entry, so what
 * changed is not a set the caller can apply on its own.
 */
issues: Array<IssueRef>, };

export type SessionIndexItem = { sessionId: string, harness: Harness, 
/**
 * Where the agent actually runs. Equals `project_path` for a normal
 * session; points inside `.claude/worktrees/<name>` for a worktree one.
 */
cwd: string, 
/**
 * Repo root — the grouping key, so worktree sessions still list under
 * their project rather than each becoming a project of their own.
 */
projectPath: string, branch: string | null, 
/**
 * `Some` marks this a worktree session; Claude Code names the branch
 * `worktree-<name>`.
 */
worktreeName: string | null, 
/**
 * This session ran in a worktree and that tree has since been deleted, so
 * `cwd` is the project root it was moved back to. The distinction is what
 * keeps `branch` above authoritative: the shared checkout's HEAD describes
 * whatever else is going on in it, not this session's work.
 */
worktreeRemoved: boolean, title: string, 
/**
 * Remembered per session so switching between sessions restores the model
 * the user last picked instead of resetting to a default.
 */
model: ModelId, 
/**
 * `None` for models that take no effort flag.
 *
 * In memory this is the true level, [`Effort::Ultra`] included. **On disk
 * it never is** — see [`encode_effort`], which is the only place the two
 * differ, and [`decode_effort`], which puts it back.
 */
effort: Effort | null, 
/**
 * Defaulted so entries written before this field read as the CLI's own
 * default rather than failing the whole index.
 */
permissionMode: ApprovalPolicy, 
/**
 * Whether the session runs at its harness's faster tier.
 *
 * **A bool and not an enum, deliberately.** Every harness with a fast mode
 * has exactly one of them — Claude Code's `fastMode` flag setting, Codex's
 * `priority` service tier, fx's `fast_mode` — and a two-valued switch is
 * the honest shape for all three. A variant is also what an older build
 * sharing `~/.hz` cannot spell, which fails the line and reads the whole
 * index as no sessions at all; `false` is what a bool degrades to there,
 * which is a session running at ordinary speed and nothing worse.
 *
 * `#[serde(default)]` for that same rule: an entry written before this
 * field reads as off rather than failing.
 */
fast: boolean, 
/**
 * Defaulted so index entries written before this field parse as `Idle`.
 */
status: SessionStatus, 
/**
 * An instruction, not a record of lineage: the session this one was forked
 * from, set until the CLI has actually forked. The fork is lazy — copying
 * this app's own log and index entry is instant, while the CLI's half only
 * happens on a spawn — so the first send resumes the parent with
 * `--fork-session` and clears this. Every send after is an ordinary resume.
 *
 * Distinct from `parent_session_id` below, which is lineage and permanent:
 * this one is cleared the moment the CLI carries the fork out.
 */
forkFrom: string | null, 
/**
 * The id the harness knows this session by, where that is not our own.
 *
 * Claude Code adopts the id the frontend mints, so this stays `None` there
 * and the two questions never come apart. `codex app-server` mints its own
 * thread id and hands it back from `thread/start`, so a Codex session has
 * two ids and this is the mapping between them.
 *
 * Ours stays primary — it keys the index, the log filename, the
 * attachments directory and every `hz` address, and all of those are
 * written *before* the child answers. This is read by resume alone.
 */
threadId: string | null, 
/**
 * The issues this session's work is against, newest link last.
 *
 * A list because one session really does carry several — three tags in one
 * prompt is the case this was built for — and a copy rather than an id,
 * so the panel's tab and the sidebar's row can be drawn with the tracker
 * unreachable. `serde(default)` so entries written before the field read
 * as untagged rather than failing the whole index.
 */
issues: Array<IssueRef>, 
/**
 * The session whose agent created this one, for a session created over the
 * orchestration socket rather than by a person in the composer. `Some` is
 * also what the depth guard reads: a session that was itself spawned may
 * not spawn more.
 */
parentSessionId: string | null, 
/**
 * The newest context reading the agent has given for this session, with the
 * moment it was taken.
 *
 * **Kept because a session outlives its child.** The reading is a question
 * only a live agent can answer — `/context` is a prompt, and the rows are
 * computed from runtime state ACP never sends — so a session reopened after
 * a restart has no way to ask one, and the panel fell back to hz's own
 * estimate of the conversation's text: a worse answer, drawn where the
 * reader had seen the agent's own rows a moment before. This is that answer
 * kept, and the panel draws it, stamped, until a live reading replaces it.
 *
 * `skip_serializing_if` so an entry without one stays byte-identical to what
 * shipped, and `serde(default)` for the reason every field here has it: the
 * index is parsed as one `Vec`, so a field an older entry lacks failing to
 * parse is *every session* gone. An older build reading this keeps it — the
 * flatten below carries keys it does not know — so the round trip through a
 * shared `~/.hz` is lossless.
 */
contextReading?: ContextReading | null, created: string, modified: string, archived: boolean, pinned: boolean, };

/**
 * Session-level facts, known at startup.
 */
export type SessionInfo = { cwd: string | null, model: string | null, harnessVersion: string | null, tools: Array<string>, mcpServers: Array<McpServer>, subagentTypes: Array<string>, settings: Settings | null, };

/**
 * What crosses the IPC boundary for one session: its index entry plus the
 * replayed event log. Distinct from [`crate::session::Session`], which owns a
 * child process and cannot be serialized.
 */
export type SessionSnapshot = { events: Array<AgentEvent>, 
/**
 * Whether `events` is the whole log. `false` on every whole-log read — a
 * new session's snapshot, a fork's copy — and on `true` the log holds
 * events older than the first one here, which the transcript fetches by
 * page once the reader reads back past this tail.
 */
hasOlder: boolean, sessionId: string, harness: Harness, 
/**
 * Where the agent actually runs. Equals `project_path` for a normal
 * session; points inside `.claude/worktrees/<name>` for a worktree one.
 */
cwd: string, 
/**
 * Repo root — the grouping key, so worktree sessions still list under
 * their project rather than each becoming a project of their own.
 */
projectPath: string, branch: string | null, 
/**
 * `Some` marks this a worktree session; Claude Code names the branch
 * `worktree-<name>`.
 */
worktreeName: string | null, 
/**
 * This session ran in a worktree and that tree has since been deleted, so
 * `cwd` is the project root it was moved back to. The distinction is what
 * keeps `branch` above authoritative: the shared checkout's HEAD describes
 * whatever else is going on in it, not this session's work.
 */
worktreeRemoved: boolean, title: string, 
/**
 * Remembered per session so switching between sessions restores the model
 * the user last picked instead of resetting to a default.
 */
model: ModelId, 
/**
 * `None` for models that take no effort flag.
 *
 * In memory this is the true level, [`Effort::Ultra`] included. **On disk
 * it never is** — see [`encode_effort`], which is the only place the two
 * differ, and [`decode_effort`], which puts it back.
 */
effort: Effort | null, 
/**
 * Defaulted so entries written before this field read as the CLI's own
 * default rather than failing the whole index.
 */
permissionMode: ApprovalPolicy, 
/**
 * Whether the session runs at its harness's faster tier.
 *
 * **A bool and not an enum, deliberately.** Every harness with a fast mode
 * has exactly one of them — Claude Code's `fastMode` flag setting, Codex's
 * `priority` service tier, fx's `fast_mode` — and a two-valued switch is
 * the honest shape for all three. A variant is also what an older build
 * sharing `~/.hz` cannot spell, which fails the line and reads the whole
 * index as no sessions at all; `false` is what a bool degrades to there,
 * which is a session running at ordinary speed and nothing worse.
 *
 * `#[serde(default)]` for that same rule: an entry written before this
 * field reads as off rather than failing.
 */
fast: boolean, 
/**
 * Defaulted so index entries written before this field parse as `Idle`.
 */
status: SessionStatus, 
/**
 * An instruction, not a record of lineage: the session this one was forked
 * from, set until the CLI has actually forked. The fork is lazy — copying
 * this app's own log and index entry is instant, while the CLI's half only
 * happens on a spawn — so the first send resumes the parent with
 * `--fork-session` and clears this. Every send after is an ordinary resume.
 *
 * Distinct from `parent_session_id` below, which is lineage and permanent:
 * this one is cleared the moment the CLI carries the fork out.
 */
forkFrom: string | null, 
/**
 * The id the harness knows this session by, where that is not our own.
 *
 * Claude Code adopts the id the frontend mints, so this stays `None` there
 * and the two questions never come apart. `codex app-server` mints its own
 * thread id and hands it back from `thread/start`, so a Codex session has
 * two ids and this is the mapping between them.
 *
 * Ours stays primary — it keys the index, the log filename, the
 * attachments directory and every `hz` address, and all of those are
 * written *before* the child answers. This is read by resume alone.
 */
threadId: string | null, 
/**
 * The issues this session's work is against, newest link last.
 *
 * A list because one session really does carry several — three tags in one
 * prompt is the case this was built for — and a copy rather than an id,
 * so the panel's tab and the sidebar's row can be drawn with the tracker
 * unreachable. `serde(default)` so entries written before the field read
 * as untagged rather than failing the whole index.
 */
issues: Array<IssueRef>, 
/**
 * The session whose agent created this one, for a session created over the
 * orchestration socket rather than by a person in the composer. `Some` is
 * also what the depth guard reads: a session that was itself spawned may
 * not spawn more.
 */
parentSessionId: string | null, 
/**
 * The newest context reading the agent has given for this session, with the
 * moment it was taken.
 *
 * **Kept because a session outlives its child.** The reading is a question
 * only a live agent can answer — `/context` is a prompt, and the rows are
 * computed from runtime state ACP never sends — so a session reopened after
 * a restart has no way to ask one, and the panel fell back to hz's own
 * estimate of the conversation's text: a worse answer, drawn where the
 * reader had seen the agent's own rows a moment before. This is that answer
 * kept, and the panel draws it, stamped, until a live reading replaces it.
 *
 * `skip_serializing_if` so an entry without one stays byte-identical to what
 * shipped, and `serde(default)` for the reason every field here has it: the
 * index is parsed as one `Vec`, so a field an older entry lacks failing to
 * parse is *every session* gone. An older build reading this keeps it — the
 * flatten below carries keys it does not know — so the round trip through a
 * shared `~/.hz` is lossless.
 */
contextReading?: ContextReading | null, created: string, modified: string, archived: boolean, pinned: boolean, };

/**
 * Driven by [`StatusTracker`](crate::session::StatusTracker). `Completed`
 * means finished *and unread* — the transition back to `Idle` is the user
 * looking at the session, not anything the agent does.
 */
export type SessionStatus = "idle" | "in_progress" | "completed";

/**
 * Emitted as `session_status` when a session's status changes, so the sidebar
 * and composer update without a refetch. Like `SessionTitleEvent`, this is not
 * an `AgentEvent`: it's derived state, and must never reach the `.jsonl` log.
 */
export type SessionStatusEvent = { sessionId: string, status: SessionStatus, 
/**
 * The entry's `modified` as the status write left it — completion bumps it,
 * and the sidebar orders by it, so a session finishing has to move to the
 * top without a refetch. `None` only when the id is no longer indexed.
 */
modified: string | null, };

/**
 * Emitted as `session_title` once a generated title lands, so the sidebar row
 * updates without a refetch. Not an `AgentEvent`: nothing here came from the
 * agent, and it must never reach the session's `.jsonl` log.
 */
export type SessionTitleEvent = { sessionId: string, title: string, };

/**
 * Settings that can change mid-session, so they arrive as events rather than
 * living only on [`SessionInfo`].
 */
export type Settings = { model: string | null, 
/**
 * How much the agent may do without asking. Modeled on Claude Code's
 * `permissionMode`, which is a closed set; Codex's `approval_policy` maps
 * onto these, gaining variants if it turns out to need them.
 */
approvalPolicy: PermissionMode | null, sandbox: string | null, writableRoots: Array<string>, networkAccess: boolean | null, fastMode: string | null, };

/**
 * What the settings dialog draws, which is not what is on disk.
 *
 * The environment can force reporting off for a run, and a switch drawn from
 * the file alone would then sit at `on` while nothing was being sent.
 * `analytics_locked` is what lets the row disable itself and say why, rather
 * than lie.
 */
export type SettingsView = { 
/**
 * Effective, not stored — the environment is already folded in.
 */
analyticsEnabled: boolean, analyticsLocked: boolean, };

/**
 * The roster as the screen reads it.
 */
export type SkillRoster = { skills: Array<PluginSkill>, 
/**
 * Whether the agent holds more than it answered with.
 */
hasMore: boolean, };

/**
 * What a switch did.
 */
export type SkillToggle = { name: string, 
/**
 * The state that was asked for.
 */
enabled: boolean, 
/**
 * **Not the same thing as `enabled`.** The registry answers nothing for a
 * Skill it does not recognise, and a screen that read the flag for the
 * outcome would draw a switch that moved over a Skill nobody changed.
 */
applied: boolean, };

/**
 * One row of the composer's slash menu.
 *
 * Defined here rather than in a shared module because there is one harness
 * left to have one, and the shape is the frontend's: it names what the menu
 * draws and nothing about where it came from.
 */
export type SlashCommand = { name: string, description: string, 
/**
 * What the command does with the rest of the line — `<model>`, `[name]`.
 * Empty for most; the CLI sends `""` rather than omitting it.
 */
argumentHint: string, 
/**
 * Other names that reach the same command. Absent on most.
 */
aliases: Array<string>, };

/**
 * Emitted as `slash_commands` when the agent states its list, which it does
 * when a session opens and again whenever the set changes.
 *
 * **Not an `AgentEvent`**, for `SessionTitleEvent`'s reason: no line of the
 * log produced it, and a replayed session has no child to have published one —
 * so it must never reach the `.jsonl`. The list belongs to the live connection
 * and crosses as it arrives, which is also why the app asks nobody for it: the
 * agent pushes, and a request made later would have to guess when.
 */
export type SlashCommandsEvent = { sessionId: string, commands: Array<SlashCommand>, };

/**
 * Git and GitHub as one read, for the settings section that explains them.
 *
 * **About the machine, not about a checkout**, and that is the whole reason it
 * is not another `cwd`-taking command: every other read here answers for one
 * repository, and the questions a reader has when pull requests will not load —
 * is `gh` even here, who is it signed in as, what may that token read — are
 * answered once for the whole app.
 */
export type SourceControlState = { 
/**
 * `git --version`'s own words, or `None` where git is not on the PATH.
 */
git: string | null, 
/**
 * `None` where the CLI is not installed at all.
 */
gh: GhAccount | null, };

/**
 * Why a press could not start recording, or `None` where it did.
 */
export type StartRefusal = { "kind": "needsModel" } | { "kind": "needsPermission" };

/**
 * A running subagent, whose events interleave with the main conversation's on
 * one stdout stream.
 *
 * Claude Code identifies these by `parent_tool_use_id` — the id of the tool
 * call that spawned it, so this equals the `call_id` of the corresponding
 * [`AgentEventPayload::ToolCallStarted`] and is what nests a subagent's work
 * under it. Codex uses `agent_path`.
 */
export type Subagent = { id: string, 
/**
 * Drives the collapsed subagent card's title.
 */
label: string | null, };

/**
 * What the webview needs to speak to PostHog for itself.
 *
 * Handed over whole rather than looked up on the other side, and that is the
 * whole of why this type exists: a frontend reading `analytics_enabled` for
 * itself would be a second reader of consent, free to answer differently from
 * this one — which is the shape DRA-199 was already caught by once. Here the
 * answer to "may I", "as whom" and "where to" is one value, and its absence is
 * the refusal.
 */
export type SurveyIdentity = { key: string, host: string, 
/**
 * The install id, so the SDK and this module are one person in PostHog
 * rather than two. Bootstrapped on the other side, never `identify`d into
 * existence — a person is already what the POSTs create.
 */
distinctId: string, 
/**
 * [`base_properties`], to be `$set` as **person** properties on the other
 * side. Event properties are what this module sends and what surveys
 * cannot target on, so without this the SDK arrives and the reason for
 * wanting it — targeting a survey at a version or an OS — still does not
 * work.
 */
personProperties: Record<string, string | number | boolean>, };

export type ToolResult = { 
/**
 * Result content flattened to text; harnesses vary between a bare string
 * and an array of blocks.
 */
text: string, 
/**
 * Harnesses routinely omit the error flag on success, so this defaults to
 * `false` rather than being treated as unknown.
 */
isError: boolean, 
/**
 * The full result payload when the harness supplies a structured one.
 */
structured: JsonValue | null, exitCode: number | null, durationMs: number | null, 
/**
 * Pictures the tool handed back — a `Read` of a screenshot, an MCP tool
 * that answers in images. Archived under `~/.hz/attachments` before the
 * event is written, so this carries a path and never the bytes: the CLI
 * sends the same image twice on one line and a session of screenshots was
 * 12MB of base64 in a 14MB log.
 */
images: Array<ImageRef>, };

/**
 * A rendering hint — which icon and component to use. Nothing depends on this
 * for correctness, and [`ToolType::Other`] must always render acceptably.
 */
export type ToolType = "shell" | "file_read" | "file_edit" | "search" | "web" | "mcp" | "subagent_spawn" | "other";

/**
 * The connected account, as the settings row draws it.
 */
export type TrackerAccount = { tracker: IssueTracker, userId: string, userName: string, orgName: string, };

/**
 * What a stop answers with.
 *
 * Every one of these is an outcome rather than an error, because the frontend
 * *acts* on each — opens settings, points at System Settings, offers a retry,
 * says nothing — where an error string could only be shown. `Failed` escaped
 * that rule for a while, and it took the recording down with it.
 *
 * `NoAudio` earns its place the hard way: macOS answers a process without
 * microphone permission with a stream of **silence** rather than a refusal, so
 * the first build of this transcribed zeros to an empty string and did nothing
 * at all, which reads exactly like a broken model.
 */
export type TranscribeOutcome = { "kind": "text", "value": string } | { "kind": "needsModel", "value": { audioPath: string | null, } } | { "kind": "noAudio" } | { "kind": "empty" } | { "kind": "failed", "value": { message: string, audioPath: string | null, } };

export type TranscriptMatch = { sessionId: string, 
/**
 * The session's title, so a row draws without a second read.
 */
title: string, 
/**
 * Position in that session's log — the ordering key, and what a reader
 * would need to be taken to the sentence.
 */
seq: number, 
/**
 * The words around the hit, elided at both ends where they were cut.
 */
snippet: string, };

/**
 * One downloadable model.
 *
 * `sha256` and `size_bytes` describe the *file*, not the repo, which is what
 * makes a half-finished download recoverable: a file on disk at the right size
 * and hash is complete whatever happened to the process that wrote it.
 */
export type TranscriptionModel = { id: string, name: string, description: string, 
/**
 * Hugging Face repo the file lives in.
 */
repo: string, 
/**
 * Pinned commit, so the URL cannot drift onto different bytes.
 */
revision: string, filename: string, sizeBytes: number, sha256: string, 
/**
 * What it transcribes, ready to draw.
 *
 * A phrase rather than a count, because the two useful answers have
 * different shapes: a handful of languages is worth *naming* — "4
 * languages" tells a French speaker nothing about whether this model is
 * for them — while ninety-nine is only ever a number. The catalog is a
 * fixed compiled-in list, so spelling it here costs nothing and keeps the
 * judgement beside the data it describes.
 */
languages: string, 
/**
 * How quick it is, 0–100, and how right it is, 0–100.
 *
 * Both are Handy's own `speed_score` / `accuracy_score` from its catalog,
 * copied rather than measured — we have run no benchmark and inventing
 * numbers that look like one would be worse than having none. They are
 * **relative to each other**, so the pair answers "which of these two"
 * and nothing about seconds or word error rate.
 */
speed: number, accuracy: number, };

/**
 * The transcription picks. Model and device mean "not chosen" when absent.
 */
export type TranscriptionSettings = { 
/**
 * A catalog id. `None` until a model is downloaded and picked, which is
 * also what makes the mic button open settings instead of recording.
 */
model: string | null, 
/**
 * An input device *name*, `None` meaning the system default.
 *
 * The name and not cpal's enumeration index: the index shifts when a USB
 * mic is unplugged, so a stored one silently starts naming a different
 * device. See [`crate::transcription::audio::InputDevice`].
 */
device: string | null, 
/**
 * Whether the speakers are silenced while the microphone is open. On by
 * default: the mic hears them, so whatever is playing otherwise lands in
 * the transcript as words nobody said.
 */
muteWhileRecording: boolean, };

/**
 * Everything the transcription tab draws in one read.
 *
 * One command rather than three, for the reason `work_status` gives: the tab
 * must not be able to show a model as installed beside a selection that
 * disagrees with it, which is what separate reads landing out of order allow.
 */
export type TranscriptionStatus = { models: Array<TranscriptionModel>, 
/**
 * Catalog ids present on disk at the right size.
 */
installed: Array<string>, 
/**
 * What the reader picked, which may name a model since deleted.
 */
selectedModel: string | null, 
/**
 * Suggested for this machine, and only a suggestion.
 */
recommended: string, devices: Array<InputDevice>, 
/**
 * Stored device name, or `None` for the system default.
 */
selectedDevice: string | null, 
/**
 * Whether the speakers are silenced while the microphone is open.
 */
muteWhileRecording: boolean, 
/**
 * False where no model is installed, or the picked one has been deleted.
 */
ready: boolean, };

/**
 * How a turn ended. Claude Code reports this as `is_error` on its result
 * event; Codex live emits `turn.completed` (a failed turn is uncaptured so
 * far). A user-abort outcome likely deserves its own variant once one has been
 * captured.
 */
export type TurnStatus = "success" | "error";

/**
 * What an undo did, so the caller can say it rather than show a diff move.
 */
export type UndoReport = { 
/**
 * Paths written back as the baseline had them.
 */
restored: number, 
/**
 * Paths the turn created, removed again.
 */
deleted: number, 
/**
 * The turn's own paths, so the reader can be told which files moved.
 */
files: Array<string>, };

export type Unreadable = "binary" | "too_large";

export type UpdateChannel = "stable" | "beta";

/**
 * What the sidebar row draws. There is no idle variant: nothing is emitted
 * until an update exists, so the frontend's own `null` is the resting state
 * and a failed check leaves the UI exactly as it was.
 */
export type UpdateStatus = { "state": "downloading", version: string, 
/**
 * `None` until the server sends a content length, which not every
 * CDN does — the row shows an indeterminate state rather than 0%.
 */
percent: number | null, } | { "state": "ready", version: string, notes: string | null, };

export type Usage = { inputTokens: number | null, outputTokens: number | null, cachedInputTokens: number | null, cacheWriteTokens: number | null, 
/**
 * Broken out only by harnesses that report it separately; others fold
 * thinking tokens into `output_tokens`.
 */
reasoningTokens: number | null, totalTokens: number | null, costUsd: number | null, contextWindow: ContextWindow | null, rateLimit: RateLimit | null, model: string | null, 
/**
 * Session-cumulative consumption, split by model. Empty on every harness
 * and every event that doesn't report one. See [`ModelUsage`].
 */
perModel: Array<ModelUsage>, };

/**
 * One cumulative usage row emitted by an agent runtime.
 *
 * Rows are optional at the wire boundary so a runtime can add fields without
 * invalidating an older desktop. `session_id` is retained in the row when the
 * runtime supplies it; the desktop fills it from the enclosing event while
 * scanning older logs.
 */
export type UsageRecord = { id: number | null, sessionId: string | null, agentName: string | null, frameworkType: string | null, turnId: string | null, model: string | null, ts: number | null, inputTokens: number | null, outputTokens: number | null, reasoningTokens: number | null, cacheReadTokens: number | null, cacheWriteTokens: number | null, costUsd: number | null, };

/**
 * The last verifier's verdict on a goal.
 */
export type Verification = { 
/**
 * `met`, `not_met`, `impossible`, `inconclusive` — the vendor's words,
 * drawn as written for `status`'s reason.
 */
verdict: string, notMetStreak: number, 
/**
 * What the verifier says is missing, where it says so.
 */
missing: Array<string>, };

/**
 * What the composer's action row needs to decide which buttons it has, in one
 * read.
 *
 * A superset of [`SyncStatus`] rather than three calls stitched together in
 * the frontend: every field here answers the same question — "what is there
 * left to do with this work" — and reading them separately would let the row
 * draw a Commit button from one snapshot beside a Push count from another.
 */
export type WorkStatus = { 
/**
 * Uncommitted paths. A count and not a list — the row only asks whether
 * there is anything, and the changes view is where the files are read.
 */
dirty: number, 
/**
 * `None` on a detached HEAD and outside a repo, which is how the row hides
 * itself entirely.
 */
branch: string | null, 
/**
 * `None` for a branch never pushed — the "publish" case.
 */
upstream: string | null, ahead: number, 
/**
 * The branch this work would land on, short of its remote (`main`, not
 * `origin/main`). Stripped here rather than in the row, so "am I on the
 * default branch" is one comparison and not a parsing rule that can drift.
 * `None` where there is no remote to ask.
 */
defaultBranch: string | null, 
/**
 * Commits this branch holds that the default branch doesn't — what a pull
 * request would actually contain.
 *
 * A different question from [`ahead`], which counts against the *upstream*:
 * a branch pushed in full is `ahead: 0` and still the one case where a pull
 * request is most wanted. Reading `ahead` for this hides the button exactly
 * when it is needed.
 *
 * `None` is "couldn't tell", not zero — `origin/HEAD` can be a symref onto
 * a ref that was never fetched, and `symbolic-ref` resolves it without
 * checking. The row treats unknown as "there may be something", since
 * over-offering costs a wasted click and under-offering hides the action.
 */
aheadOfBase: number | null, };

/**
 * One job in a run, and how far it got.
 */
export type WorkflowJob = { id: number, 
/**
 * The job's key in the workflow file, which is also what GitHub's own page
 * heads the block with (`build`, `release`).
 */
name: string, status: string, conclusion: string | null, 
/**
 * When a runner picked it up. **Not a proxy for "it ran"** — a job skipped
 * by its own `if:` carries a stamp here too, and its empty step list is what
 * says it did nothing.
 */
startedAt: string | null, completedAt: string | null, 
/**
 * **Empty is a fact, not a gap.** A job skipped by an `if:` has no steps at
 * all, and a list that drew it as "no steps reported" would be guessing at
 * which of the two it was.
 */
steps: Array<WorkflowStep>, };

/**
 * One workflow run, as the Actions row draws it.
 *
 * **A row's worth and no more.** Which step failed, what artifact it left and
 * how long each job took are all one `gh run view` away, and a page that read
 * them for thirty runs would be thirty spawns for facts nobody scrolls past —
 * the same bargain [`PrListItem`] makes against [`PullRequest`].
 *
 * `status` and `conclusion` ride GitHub's own words rather than a fold, because
 * there is nothing to fold: one run has one of each, and the mapping to a glyph
 * and a colour is the frontend's — the split [`PrListItem::state`] makes.
 */
export type WorkflowRun = { 
/**
 * GitHub's own id for the run: what a re-run or a cancel would address, and
 * what the row is keyed by. Not the number, which is unique only within its
 * workflow.
 */
id: number, 
/**
 * The run's number within its workflow — the `#70` GitHub's own page shows.
 */
number: number, 
/**
 * Which attempt this is. A re-run increments it, so `2` is a run that failed
 * once and was asked again; drawn only above one.
 */
attempt: number, 
/**
 * The workflow's name as the repository declares it (`Release`, `Warm
 * cache`).
 */
workflow: string, 
/**
 * What the run is about: the commit subject it was started for, or the
 * workflow's own name for a run GitHub starts on its own behalf
 * (`pages build and deployment`).
 */
title: string, branch: string, sha: string, 
/**
 * What asked for it — `push`, `pull_request`, `workflow_dispatch`,
 * `schedule`, or `dynamic` for GitHub's own.
 */
event: string, 
/**
 * `queued`, `in_progress`, `completed`, as GitHub spells them.
 */
status: string, 
/**
 * `success`, `failure`, `cancelled`, `skipped`, `timed_out`… and `None`
 * while the run has not finished, which is not the same fact as a
 * conclusion nobody has given.
 */
conclusion: string | null, createdAt: string, 
/**
 * When a runner picked it up. `None` while it is still queued, which is the
 * whole difference between waiting for a machine and running on one.
 */
startedAt: string | null, 
/**
 * When it last moved — the end of the run, for one that has finished.
 */
updatedAt: string, url: string, };

/**
 * Everything `gh run view` knows about one run, which is a row plus its jobs.
 *
 * **One extra spawn, and only for the run the reader asked about.** Which step
 * failed is the question a red row raises, and the answer is a job list the
 * listing does not carry: thirty of those would be thirty `gh run view` calls
 * for a pane that shows one.
 */
export type WorkflowRunDetail = { run: WorkflowRun, jobs: Array<WorkflowJob>, };

/**
 * One step of a job. Steps are not addressable — nothing re-runs or cancels one
 * — so this is the number the run's own page shows, and nothing else.
 */
export type WorkflowStep = { number: number, name: string, status: string, conclusion: string | null, startedAt: string | null, completedAt: string | null, };

/**
 * What removing this worktree would cost, read once so the dialog and the
 * removal agree about what is in the way.
 */
export type WorktreeDisposition = { 
/**
 * `false` once the directory is gone — removed by hand, or by a `claude`
 * run that did have an exit prompt. The caller skips the dialog and goes
 * straight to relocating the session, so a half-dead tree tidies itself
 * up rather than asking a question about a directory nobody can see.
 */
exists: boolean, 
/**
 * `git status --porcelain` lines: modified, staged, and untracked alike.
 */
changedFiles: number, 
/**
 * Commits **only this branch holds** — reachable from its HEAD and from
 * no other branch, remote or tag. That is the question the reader is
 * actually asking, since a commit some other ref also holds survives the
 * branch being deleted.
 *
 * Counting against remotes alone was the first version and was wrong in
 * the plainest case: a repo with no remote at all reported every commit
 * in its history as at risk, so a spotless worktree warned about the
 * initial commit.
 *
 * A squash-merged PR still counts, since its commits are genuinely on no
 * other ref whatever landed on `main`. The CLI's own exit prompt has the
 * same blind spot; it over-warns, which is the safe direction.
 */
unpushedCommits: number, 
/**
 * The reason string on git's own lock, when one is held by a **live**
 * process. `None` covers both the unlocked tree and the far commoner
 * case of a lock left behind by a session that has since exited.
 */
lockedBy: string | null, };
